//! 🛡️ Header probes spend a real Source-table hold and settle only at their original observer.
use super::*;
fn bad()->ValueError{refused("header guard changed its actual Source, permit or receipt")}
pub use semio_framework_job_payload::OriginalReturnGuardPermit;
fn source(cx:&StepContext<'_>)->Result<(usize,u64,usize),OriginalTurnFailure>{let parent=cx.original_source_parent()?;parent.validate_borrowed_context(cx)?;OriginalReturnSourceInput::capture(cx)?;let b=cx.original_return_budget().ok_or_else(bad)?.get();let origin=b.origin().ok_or_else(bad)?;if origin.source!=parent.source_identity()?||origin.recipient!=b as*const _ as usize{return Err(bad().into())}Ok((origin.source,b.birth,origin.recipient))}
/// 🌱️ The same Source reserves exact guard metadata and two work units before publishing its header.
pub fn prepare_original_header_guard(cx:&mut StepContext<'_>,permit:&mut Option<OriginalReturnGuardPermit>,length:usize)->Result<bool,OriginalTurnFailure>{
 let(source_id,birth,recipient)=source(cx)?;let epoch=cx.original_source_epoch().filter(|e|*e!=0).ok_or_else(bad)?;if !matches!(length,144|152|184){return Err(bad().into())}
 let budget=cx.original_return_budget().unwrap().get();if budget.delivery!=OriginalReturnDelivery::CoreWireSnapshot||budget.publisher_fenced||budget.publication.is_some(){return Err(bad().into())}let pointer=budget.publisher().filter(|_|budget.publisher_placed).ok_or_else(bad)?.preborn_header_address();
 if let Some(p)=permit.as_ref(){let id=p.identity();if id.source!=source_id as u64||id.source_birth!=birth||id.recipient!=recipient as u64||id.extent!=length as u64||id.destination!=pointer as u64{return Err(bad().into())}budget.table().ok_or_else(bad)?.qualify_guard(permit,pointer)?;return Ok(true)}
 let copy=OriginalReturnEscrowTable::guard_mint_copy_demand();let progress=P{copied_items:1,copied_bytes:copy,..Default::default()};let mut proposed=budget.snapshot();proposed.advance_retained(progress).map_or(Ok(()),|issue|Err(refused(issue.failure().1)))?;if let Some(issue)=proposed.advance_work(1){return Err(refused(issue.failure().1).into())}let plan=proposed.plan_guard()?;
 if (if cx.original_retirement_active(){cx.retirement_should_yield()}else{cx.is_cancelled()||cx.should_yield()})||!cx.retained_recipient_is_admitted(){return Ok(false)}let grant=cx.retained_grant();if grant.maximum_items==0||grant.maximum_copy_bytes<copy||grant.maximum_depth==0||cx.fuel_remaining()==0{return Ok(false)}cx.retained_progress().checked_add(progress)?;
 let b=cx.original_return_budget_mut().unwrap().get_mut();let table=b.table_mut().ok_or_else(bad)?;let identity=OriginalReturnEscrowIdentity{source:source_id as u64,source_birth:birth,recipient:recipient as u64,destination:pointer as u64,extent:length as u64,serial:plan.serial,origin_epoch:epoch};if !table.reserve_guard(identity,permit)?{return Ok(false)}b.serial=plan.serial;b.claims=plan.claims;b.held_items=plan.held_items;b.held_copy_bytes=plan.held_copy_bytes;b.held_fuel=plan.held_fuel;let posted=cx.consume_retained(progress);cx.consume_fuel(1);posted?;Ok(true)
}
/// 🔎️ Exposure requires the actual preborn header address and its still-unspent table-issued permit.
pub fn qualify_original_header_guard(cx:&StepContext<'_>,permit:&Option<OriginalReturnGuardPermit>,length:usize)->Result<(),OriginalTurnFailure>{
 let(s,birth,r)=source(cx)?;let b=cx.original_return_budget().unwrap().get();let p=permit.as_ref().ok_or_else(bad)?;let id=p.identity();let pointer=b.publisher().ok_or_else(bad)?.preborn_header_address();if id.source!=s as u64||id.source_birth!=birth||id.recipient!=r as u64||id.destination!=pointer as u64||id.extent!=length as u64{return Err(bad().into())}b.table().ok_or_else(bad)?.qualify_guard(permit,pointer)?;Ok(())
}
/// ⚡️ Only an already selected physical header loan may spend this no-context probe.
pub fn check_original_header_guard(parent:&crate::OriginalCallerSourceParent,permit:&mut Option<OriginalReturnGuardPermit>,pointer:usize)->Result<bool,ValueError>{let source=parent.return_source()?;let mut budget=source.try_borrow().ok_or_else(bad)?;let b=budget.get_mut();let origin=b.origin().ok_or_else(bad)?;let id=permit.as_ref().ok_or_else(bad)?.identity();let publisher=b.publisher().ok_or_else(bad)?;if id.source!=origin.source as u64||id.source_birth!=b.birth||id.recipient!=origin.recipient as u64||id.destination!=publisher.preborn_header_address()as u64||b.publication.is_none()||b.publisher_fenced{return Err(bad())}let address=id.destination as usize;b.table_mut().ok_or_else(bad)?.begin_guard_check(permit,address)?;Ok(b.publisher().unwrap().owns_header_pointer(pointer))}
/// 🧾️ Actual observation posts the prepaid probe separately from fresh receipt effects.
pub fn observe_original_header_guard(cx:&mut StepContext<'_>,permit:&mut Option<OriginalReturnGuardPermit>)->Result<bool,OriginalTurnFailure>{settle(cx,permit,false)}
/// ↩️ An unused guard releases its exact held stock under its original Source.
pub fn release_original_header_guard(cx:&mut StepContext<'_>,permit:&mut Option<OriginalReturnGuardPermit>)->Result<bool,OriginalTurnFailure>{settle(cx,permit,true)}
fn settle(cx:&mut StepContext<'_>,permit:&mut Option<OriginalReturnGuardPermit>,release:bool)->Result<bool,OriginalTurnFailure>{
 let Some(p)=permit.as_ref()else{return Ok(true)};let(s,birth,r)=source(cx)?;let id=p.identity();if id.source!=s as u64||id.source_birth!=birth||id.recipient!=r as u64{return Err(bad().into())}let pending=p.pending();let spent=match pending{Some((_,work))=>work!=0,None if release=>false,None=>return Err(bad().into())};if pending.is_none()&&cx.original_return_budget().unwrap().get().publication.is_some(){return Err(bad().into())}
 let progress=P{copied_items:1+usize::from(spent),copied_bytes:OriginalReturnEscrowTable::guard_observe_copy_bytes(spent)+if spent{OriginalReturnEscrowTable::guard_check_copy_bytes()}else{0},..Default::default()};let work=1+if spent{2}else{0};cx.preflight_original_reserved_return(progress,work)?;let plan=cx.original_return_budget().unwrap().get().snapshot().plan_guard_settlement(spent)?;
 let b=cx.original_return_budget_mut().unwrap().get_mut();let table=b.table_mut().ok_or_else(bad)?;if pending.is_none(){table.release_guard(permit)?;}table.finish_guard(permit)?;b.claims=plan.claims;b.held_items=plan.held_items;b.held_copy_bytes=plan.held_copy_bytes;b.held_fuel=plan.held_fuel;b.spent=plan.spent;b.work=plan.work;cx.receive_original_reserved_return(progress,work)?;Ok(true)
}
